// Registers an entry while it loads, and reads the DOM through dom-reader.
const registry = require('cyclic-registry')
const domReader = require('dom-reader')
class PluginEntry extends registry.Entry {}
exports.entry = registry.register('plugin', new PluginEntry('plugin'))
exports.agent = domReader.agent
